顺序结构：先算总价 sum = x+y+z，再算找零 100-sum，依次输出。

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    int x, y, z;
    cin >> x >> y >> z;
    int sum = x + y + z;
    cout << sum << endl;
    cout << 100 - sum << endl;
    return 0;
}
```

选择结构：if (m >= 50) m -= 10; 再输出 m。边界 50 也减 10。

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    int m;
    cin >> m;
    if (m >= 50) m -= 10;
    cout << m << endl;
    return 0;
}
```

循环结构：for (i=1; i<=n; i++) sum += i; 累加 1 到 n。

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, sum = 0;
    cin >> n;
    for (int i = 1; i <= n; i++)
        sum += i;
    cout << sum << endl;
    return 0;
}
```

计数排序统计票数：cnt[7] 按动物编号作下标统计，cnt[x]++。再遍历找票数最多者，仅当 cnt[i] > cnt[winner] 时更新，严格大于保证平票取编号小者。

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, cnt[7] = {0};
    cin >> n;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        cnt[x]++;
    }
    int winner = 1;
    for (int i = 2; i <= 6; i++)
        if (cnt[i] > cnt[winner]) winner = i;
    cout << winner << endl;
    return 0;
}
```

计数排序统计频次：cnt[7] 按点数作下标统计，cnt[x]++，最后从 1 到 6 输出。

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, cnt[7] = {0};
    cin >> n;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        cnt[x]++;
    }
    for (int i = 1; i <= 6; i++)
        cout << i << ":" << cnt[i] << endl;
    return 0;
}
```
